using System.Text.Json;
using ArenaDesktopCompanion.Core.Settings;
using ArenaDesktopCompanion.Core.Tests.Support;
namespace ArenaDesktopCompanion.Core.Tests;
public class Rc30LifecycleTests
{
    private const string Chat="https://arena.ai/agent/00000000-0000-4000-8000-000000000003";
    private static Arbeitsbereich Tab(string root)=>new(){ProjectFolder=root,BridgeBin="adc-lifecycle-test1",BridgeToken="synthetic-only-key",BridgeEncrypted=true,ConnectionId=Guid.NewGuid().ToString("N"),ConnectedChatAddress=Chat,ChatAddress=Chat,LetzteAdresse=Chat,Name="Arena-Projekt",Group="Gruppe",Panels=[new(){Kind="logs",Detached=true}]};
    [Theory][InlineData("https://arena.ai/agent")][InlineData("https://arena.ai/agent/")][InlineData("https://www.arena.ai/agent")]
    public void Starter_is_recorded_without_inventing_a_chat_id(string raw)=>Assert.Equal("https://arena.ai/agent",ChatIdentity.Address(raw));
    [Fact]public void Current_chat_is_canonicalized_without_query_or_fragment()=>Assert.Equal(Chat,ChatIdentity.Address(Chat+"?debug=1#fragment"));
    [Theory][InlineData("https://arena.ai.evil.test/agent/00000000-0000-4000-8000-000000000003")][InlineData("http://arena.ai/agent")][InlineData("https://arena.ai:444/agent")][InlineData("https://user@arena.ai/agent")][InlineData("https://arena.ai/agent/settings")][InlineData("https://arena.ai/agent/not-a-uuid")][InlineData("https://arena.ai/login")][InlineData("https://outside.test/agent")]
    public void Non_chat_and_untrusted_addresses_are_ignored(string raw)=>Assert.Null(ChatIdentity.Address(raw));
    [Theory][InlineData("Arena")][InlineData("LMArena")][InlineData("New chat")][InlineData("Neuer Chat")][InlineData("Arena | Benchmark & Compare the Best AI Models")][InlineData("Arena – AI Chat")][InlineData("Arena | Free Chat")]
    public void Generic_document_titles_are_not_chat_names(string raw)=>Assert.Null(ChatIdentity.Title(raw));
    [Fact]public void Document_title_suffix_is_removed()=>Assert.Equal("Mein Projekt",ChatIdentity.Title("Mein Projekt – Arena"));
    [Fact]public void Exact_user_name_is_preserved_even_when_named_arena()=>Assert.Equal("Arena",ChatIdentity.Name(" Arena "));
    [Fact]public void Downloads_default_off_but_auto_import_on(){Assert.False(new Arbeitsbereich().RouteDownloads);Assert.False(new AppSettings().RouteDownloadsToInbox);Assert.True(new Arbeitsbereich().AutoImport);}
    [Fact]public void Preference_migration_runs_only_once(){var s=new AppSettings();s.ArbeitsbereichAnlegen();s.Arbeitsbereiche[0].RouteDownloads=true;s.ApplyRc30Preferences();Assert.False(s.Arbeitsbereiche[0].RouteDownloads);s.Arbeitsbereiche[0].RouteDownloads=true;s.ApplyRc30Preferences();Assert.True(s.Arbeitsbereiche[0].RouteDownloads);}
    [Fact]public void Close_restore_keeps_complete_identity_and_uses_snapshot(){using var t=new TempTree();var a=Tab(t.Root);var b=Tab(t.Root);var s=new AppSettings{Arbeitsbereiche=[a,b]};Assert.True(TabHistory.Close(s,a.Id,DateTimeOffset.UtcNow));a.Name="disposed UI change";a.Panels[0].Detached=false;var r=TabHistory.Restore(s,a.Id)!;Assert.Equal("Arena-Projekt",r.Name);Assert.True(r.Panels[0].Detached);Assert.Equal(a.Id,r.Id);Assert.Equal(a.BridgeToken,r.BridgeToken);Assert.Equal(a.ConnectionId,r.ConnectionId);Assert.Equal(Chat,r.ChatAddress);Assert.Equal(t.Root,r.ProjectFolder);Assert.Equal("Gruppe",r.Group);Assert.Empty(s.ClosedWorkspaces);}
    [Fact]public void Last_tab_can_close_and_gets_empty_replacement(){var s=new AppSettings();s.ArbeitsbereichAnlegen();var id=s.Arbeitsbereiche[0].Id;Assert.True(TabHistory.Close(s,id,DateTimeOffset.UtcNow));Assert.Single(s.Arbeitsbereiche);Assert.NotEqual(id,s.Arbeitsbereiche[0].Id);Assert.Null(s.Arbeitsbereiche[0].ProjectFolder);Assert.Single(s.ClosedWorkspaces);}
    [Fact]public void Closing_background_tab_preserves_active_tab(){var s=new AppSettings();for(var i=0;i<3;i++)s.ArbeitsbereichAnlegen();s.AktiverArbeitsbereich=2;var active=s.Arbeitsbereiche[2].Id;TabHistory.Close(s,s.Arbeitsbereiche[0].Id,DateTimeOffset.UtcNow);Assert.Equal(active,s.Arbeitsbereiche[s.AktiverArbeitsbereich].Id);}
    [Fact]public void Restoring_unknown_or_duplicate_history_is_a_noop(){var s=new AppSettings();s.ArbeitsbereichAnlegen();Assert.Null(TabHistory.Restore(s,"missing"));s.ClosedWorkspaces.Add(new(){Tab=s.Arbeitsbereiche[0]});Assert.Null(TabHistory.Restore(s,s.Arbeitsbereiche[0].Id));}
    [Fact]public void Forget_removes_only_closed_metadata_not_project(){using var t=new TempTree();t.Write("keep.txt","user");var a=Tab(t.Root);var s=new AppSettings{Arbeitsbereiche=[a]};TabHistory.Close(s,a.Id,DateTimeOffset.UtcNow);Assert.True(TabHistory.Forget(s,a.Id));Assert.Empty(s.ClosedWorkspaces);Assert.Equal("user",t.Read("keep.txt"));Assert.False(TabHistory.Forget(s,s.Arbeitsbereiche[0].Id));}
    [Fact]public void History_and_settings_survive_serialization(){var s=new AppSettings();s.ArbeitsbereichAnlegen();TabHistory.Close(s,s.Arbeitsbereiche[0].Id,DateTimeOffset.UtcNow);var r=JsonSerializer.Deserialize<AppSettings>(JsonSerializer.Serialize(s))!;Assert.Equal(s.ClosedWorkspaces[0].Tab.Id,r.ClosedWorkspaces[0].Tab.Id);Assert.Equal(s.ClosedWorkspaces[0].ClosedAt,r.ClosedWorkspaces[0].ClosedAt);}
    [Fact]public void Normalization_rejects_unsafe_duplicate_and_live_cleanup_ids(){var s=new AppSettings();s.ArbeitsbereichAnlegen();var live=s.Arbeitsbereiche[0];s.ClosedWorkspaces=[new(){Tab=live},new(){Tab=new(){Id="../escape"}}];s.PendingTabCleanup=[live.Id,"../escape"];TabHistory.Normalize(s);Assert.Empty(s.ClosedWorkspaces);Assert.Empty(s.PendingTabCleanup);}
    [Fact]public void Valid_resume_preserves_old_contact_time_not_now(){using var t=new TempTree();var a=Tab(t.Root);var seen=DateTimeOffset.UtcNow.AddDays(-1);var p=PeerResumeState.Create(a,seen);Assert.True(p.Matches(a,DateTimeOffset.UtcNow));Assert.Equal(seen,p.LastSeen);}
    [Theory][InlineData("root")][InlineData("token")][InlineData("mailbox")][InlineData("connection")][InlineData("chat")][InlineData("id")]
    public void Changed_binding_invalidates_resume(string field){using var t=new TempTree();var a=Tab(t.Root);var p=PeerResumeState.Create(a,DateTimeOffset.UtcNow);switch(field){case "root":a.ProjectFolder+="-other";break;case "token":a.BridgeToken+="-other";break;case "mailbox":a.BridgeBin+="-other";break;case "connection":a.ConnectionId+="-other";break;case "chat":a.ConnectedChatAddress="https://arena.ai/agent/00000000-0000-4000-8000-000000000002";break;case "id":a.Id=Guid.NewGuid().ToString("N");break;}Assert.False(p.Matches(a,DateTimeOffset.UtcNow));}
    [Fact]public void Tampered_resume_cannot_claim_fresh_contact(){using var t=new TempTree();var a=Tab(t.Root);var p=PeerResumeState.Create(a,DateTimeOffset.UtcNow.AddDays(-1));Assert.False((p with{LastSeen=DateTimeOffset.UtcNow}).Matches(a,DateTimeOffset.UtcNow));Assert.False((p with{Signature="broken"}).Matches(a,DateTimeOffset.UtcNow));}
    [Fact]public void Future_resume_rejected(){using var t=new TempTree();var a=Tab(t.Root);Assert.False(PeerResumeState.Create(a,DateTimeOffset.UtcNow.AddHours(1)).Matches(a,DateTimeOffset.UtcNow));}
}
